import{_ as e,c as a,ah as r,o}from"./chunks/framework.dXI2wdDN.js";const u=JSON.parse('{"title":"CC Switch：一款管理 8 款 AI 编程工具配置的桌面切换器","description":"","frontmatter":{"title":"CC Switch：一款管理 8 款 AI 编程工具配置的桌面切换器","date":"2026-08-13T00:00:00.000Z","author":"leeyazhou","categories":["AI编程工具"],"tags":["ClaudeCode","AI","效率工具","终端工具"]},"headers":[],"relativePath":"blog/ai/ide/cc-switch.md","filePath":"blog/ai/ide/cc-switch.md","lastUpdated":1786611013000}'),i={name:"blog/ai/ide/cc-switch.md"};function d(l,t,c,h,n,s){return o(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1786579200000"},[...t[0]||(t[0]=[r('<h1 id="cc-switch-一款管理-8-款-ai-编程工具配置的桌面切换器" tabindex="-1">CC Switch：一款管理 8 款 AI 编程工具配置的桌面切换器 <a class="header-anchor" href="#cc-switch-一款管理-8-款-ai-编程工具配置的桌面切换器" aria-label="Permalink to &quot;CC Switch：一款管理 8 款 AI 编程工具配置的桌面切换器&quot;">​</a></h1><p>做 AI 编程的人，手上大概率不止一个工具：Claude Code、Codex、Gemini CLI、OpenCode、Grok Build……每个工具都有自己的一套配置格式——JSON、TOML、<code>.env</code>，切换 API 供应商意味着手动改文件、来回折腾。</p><p><a href="https://ccswitch.io" target="_blank" rel="noreferrer">CC Switch</a> 就是为了终结这种折腾而生的。它是一个跨平台桌面应用（基于 Tauri 2），把 8 款主流 AI 编程工具的配置管理统一到一个图形界面里。</p><h2 id="它支持哪些工具" tabindex="-1">它支持哪些工具 <a class="header-anchor" href="#它支持哪些工具" aria-label="Permalink to &quot;它支持哪些工具&quot;">​</a></h2><p>CC Switch 目前支持 8 款工具：</p><table tabindex="0"><thead><tr><th>工具</th><th>说明</th></tr></thead><tbody><tr><td>Claude Code</td><td>Anthropic 的终端编程助手</td></tr><tr><td>Claude Desktop</td><td>Claude 桌面应用</td></tr><tr><td>Codex</td><td>OpenAI 的编程代理</td></tr><tr><td>Gemini CLI</td><td>Google 的终端 AI</td></tr><tr><td>Grok Build</td><td>xAI 的编程工具</td></tr><tr><td>OpenCode</td><td>终端 AI 编程助手</td></tr><tr><td>OpenClaw</td><td>开源 AI 代理</td></tr><tr><td>Hermes Agent</td><td>通用代理框架</td></tr></tbody></table><blockquote><p>官方仓库：<a href="https://github.com/farion1231/cc-switch" target="_blank" rel="noreferrer">github.com/farion1231/cc-switch</a>。唯一官网是 <strong>ccswitch.io</strong>。</p></blockquote><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="_1-一键导入-即时切换" tabindex="-1">1. 一键导入 + 即时切换 <a class="header-anchor" href="#_1-一键导入-即时切换" aria-label="Permalink to &quot;1. 一键导入 + 即时切换&quot;">​</a></h3><p>内置 50+ 供应商预设（AWS Bedrock、NVIDIA NIM、社区中转等），复制 API Key 后一键导入。切换供应商只需选中 → 点「启用」，不用再手改配置文件。</p><h3 id="_2-系统托盘快速切换" tabindex="-1">2. 系统托盘快速切换 <a class="header-anchor" href="#_2-系统托盘快速切换" aria-label="Permalink to &quot;2. 系统托盘快速切换&quot;">​</a></h3><p>托盘菜单里直接点供应商名即可切换，无需打开完整应用。对频繁在不同供应商间横跳的人来说，这是最实用的功能。</p><h3 id="_3-统一-mcp-与-skills-管理" tabindex="-1">3. 统一 MCP 与 Skills 管理 <a class="header-anchor" href="#_3-统一-mcp-与-skills-管理" aria-label="Permalink to &quot;3. 统一 MCP 与 Skills 管理&quot;">​</a></h3><p>一个面板管理跨 Claude、Codex、Gemini、Grok Build、OpenCode、Hermes 的 MCP 服务器和 Skills，支持双向同步。</p><h3 id="_4-prompts-同步" tabindex="-1">4. Prompts 同步 <a class="header-anchor" href="#_4-prompts-同步" aria-label="Permalink to &quot;4. Prompts 同步&quot;">​</a></h3><p>Markdown 编辑器管理 <code>CLAUDE.md</code> / <code>AGENTS.md</code> / <code>GEMINI.md</code> 等提示词文件，跨应用同步。</p><h3 id="_5-云同步" tabindex="-1">5. 云同步 <a class="header-anchor" href="#_5-云同步" aria-label="Permalink to &quot;5. 云同步&quot;">​</a></h3><p>通过 Dropbox、OneDrive、iCloud 或 WebDAV 在多台设备间同步供应商配置。</p><h3 id="_6-可靠的存储" tabindex="-1">6. 可靠的存储 <a class="header-anchor" href="#_6-可靠的存储" aria-label="Permalink to &quot;6. 可靠的存储&quot;">​</a></h3><p>配置存 SQLite，原子写入，避免切换过程中配置损坏。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ul><li><strong>macOS</strong>：官网下载 <code>.dmg</code>，已由 Apple 签名和公证，直接安装即可。</li><li><strong>Windows / Linux</strong>：从 <a href="https://github.com/farion1231/cc-switch/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 下载对应安装包。</li></ul><h2 id="使用流程" tabindex="-1">使用流程 <a class="header-anchor" href="#使用流程" aria-label="Permalink to &quot;使用流程&quot;">​</a></h2><ol><li><strong>添加供应商</strong>：点「Add Provider」→ 选预设或自定义配置（填 API Key、Base URL、模型名）。</li><li><strong>切换供应商</strong>：主界面选中 → 点「Enable」，或从系统托盘直接点。</li><li><strong>生效</strong>：重启终端或对应 CLI（Claude Code 例外，支持热切换无需重启）。</li><li><strong>回到官方登录</strong>：添加「Official Login」预设，重启 CLI 后走 OAuth 流程。</li></ol><h2 id="几个常见问题" tabindex="-1">几个常见问题 <a class="header-anchor" href="#几个常见问题" aria-label="Permalink to &quot;几个常见问题&quot;">​</a></h2><p><strong>切换后插件配置消失了？</strong> 这是「共享配置片段」（Shared Config Snippet）机制——在「Edit Provider → Shared Config Panel → Extract from Current Provider」把公共配置（插件等）提取保存，新建供应商时勾选「Write Shared Config」即可带上。</p><p><strong>为什么删不掉当前启用的供应商？</strong> 这是「最小侵入」设计——即使卸载应用，CLI 也能正常工作。系统始终保留一个启用配置，因为删光配置会导致对应 CLI 不可用。</p><p><strong>配置存哪了？</strong> 本地 SQLite + 可选的备份目录，可导出到设备级备份。</p><h2 id="cli-版本" tabindex="-1">CLI 版本 <a class="header-anchor" href="#cli-版本" aria-label="Permalink to &quot;CLI 版本&quot;">​</a></h2><p>如果你更喜欢命令行，社区也有几个 CLI 实现：</p><ul><li><a href="https://github.com/bigwhite/cc-switch-cli" target="_blank" rel="noreferrer">bigwhite/cc-switch-cli</a>：<code>add</code> / <code>list</code> / <code>use</code> / <code>current</code> 等子命令，原子写入 + 自动备份。</li><li><a href="https://github.com/SaladDay/cc-switch-cli" target="_blank" rel="noreferrer">SaladDay/cc-switch-cli</a>：CC Switch 的 CLI 分支，TUI + 脚本化，WebDAV 同步与上游兼容。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>CC Switch 的价值在于「一个界面管理所有 AI 工具的供应商配置」。如果你同时用多个 AI 编程工具、或者经常在不同 API 供应商（官方、第三方中转、本地 Ollama）之间切换，它能省下大量手动改配置的时间。</p><p>配合 <a href="./oh-my-openagent.html">oh-my-openagent</a> 这样的编排插件，加上一个统一的配置切换器，AI 编程工作流的「工具层」就基本齐活了。</p><p><strong>相关链接</strong></p><ul><li>官网：<a href="https://ccswitch.io" target="_blank" rel="noreferrer">https://ccswitch.io</a></li><li>GitHub：<a href="https://github.com/farion1231/cc-switch" target="_blank" rel="noreferrer">https://github.com/farion1231/cc-switch</a></li></ul>',36)])])}const b=e(i,[["render",d]]);export{u as __pageData,b as default};
